pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";
import {CoolerFactory} from "../src/C_under_test.sol";
import {ERC20} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    CoolerFactory factory;
    ERC20 collateral;
    ERC20 debt;

    function setUp() public {
        c = new C();
        factory = new CoolerFactory();
    }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Approve and generate a cooler for caller
        vm.prank(caller);
        address cooler = factory.generateCooler(collateral, debt);
        // The cooler should have owner() equal to caller
        C coolerContract = C(payable(cooler));
        // Now call approveTransfer on the cooler
        address randomSpender = address(0x1234);
        uint256 loanID = 0;
        // Need a request and loan first to have a valid loanID
        // For simplicity, test that the owner() returns the caller in any case
        // But the bug makes owner() return address(0), so we can check that
        vm.prank(caller);
        coolerContract.approveTransfer(randomSpender, loanID);
        // This call should revert if owner() != caller (since onlyApproved)
        // But the bug makes owner() always address(0), so the call reverts
        // Instead, check the invariant: owner() should always equal the caller for which the cooler was created
        assertTrue(coolerContract.owner() == caller);
    }
}

