pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address nonLender, uint256 loanID) public {
        // Ensure nonLender is not the owner and loanID is within valid range
        vm.assume(nonLender != address(0));
        vm.assume(nonLender != c.owner());

        // Bound loanID to a reasonable range
        loanID = bound(loanID, 0, 100);

        // Get the collateral address before calling approveTransfer
        address collateralBefore = address(c.collateral());

        // Try to call approveTransfer as nonLender (should revert with OnlyApproved)
        vm.prank(nonLender);
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("approveTransfer(address,uint256)", address(0), loanID)
        );

        // Get the collateral address after the failed call
        address collateralAfter = address(c.collateral());

        // The collateral address must remain unchanged
        assertTrue(collateralBefore == collateralAfter, "Collateral address changed after failed approveTransfer");
    }
}

