contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address to, uint256 loanID) public {
        vm.assume(loanID < c.loans().length || c.requests().length > 0);
        // The collateral address is read from immutable args: it must match the owner
        // (first arg) for any loan or request that exists.
        address coll = address(c.collateral());
        address owner = c.owner();
        // The bug changes the offset, making collateral() return the wrong address
        assertTrue(coll == owner || uint256(uint160(coll)) == uint256(uint160(owner)));
    }
}

