pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address lender, address to) public {
        vm.assume(owner != address(0) && lender != address(0) && to != address(0));
        vm.assume(owner != lender && owner != to && lender != to);

        // Generate a cooler with owner as the user
        address cooler;
        {
            // Use a simple approach: deploy the C contract directly (already done in setUp)
            // We need to create a loan to call approveTransfer
            // First, fund the contract with collateral tokens
            vm.deal(owner, 1 ether);
            vm.prank(owner);
            c.requestLoan(100, 1000000000000000000, 1000000000000000000, 100);
        }

        // Now clear request to create a loan
        vm.prank(lender);
        (bool clearSuccess,) = address(c).call(
            abi.encodeWithSignature("clearRequest(uint256,bool,bool)", 0, false, false)
        );
        vm.assume(clearSuccess);

        // Call approveTransfer as the lender
        vm.prank(lender);
        c.approveTransfer(to, 0);

        // Assert that collateral() and debt() return different addresses
        assertTrue(c.collateral() != c.debt());
    }
}

