contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address alice, address bob, uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration, bool repayDirect, bool isCallback) public {
        vm.assume(alice != address(0) && bob != address(0));
        vm.assume(alice != bob);
        amount = bound(amount, 1, 1e30);
        interest = bound(interest, 0, 1e18);
        loanToCollateral = bound(loanToCollateral, 1, 1e18);
        duration = bound(duration, 1, 36500 days);

        // First need to create a loan: request then clear
        vm.prank(alice);
        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration);

        vm.prank(bob);
        uint256 loanID = c.clearRequest(reqID, repayDirect, isCallback);

        // Bob approves alice to transfer ownership
        vm.prank(bob);
        c.approveTransfer(alice, loanID);

        // Alice calls transferOwnership - should succeed
        vm.prank(alice);
        (bool success, ) = address(c).call(abi.encodeWithSignature("transferOwnership(uint256)", loanID));

        assertTrue(success, "transferOwnership should succeed for approved address");
    }
}

