    ) public {
        vm.assume(owner != address(0) && newOwner != address(0) && owner != newOwner);
        vm.assume(amount > 0 && amount <= 1e24);
        vm.assume(interest > 0 && interest <= 1e18);
        vm.assume(loanToCollateral > 0 && loanToCollateral <= 1e6);
        vm.assume(duration > 0 && duration <= 365 days);
        vm.assume(repayAmount > 0 && repayAmount <= amount);

        // Setup: owner makes a request
        vm.startPrank(owner);
        deal(address(c.collateral()), owner, 1e24);
        deal(address(c.debt()), owner, 1e24);
        c.collateral().approve(address(c), type(uint256).max);
        c.debt().approve(address(c), type(uint256).max);
        uint256 reqId = c.requestLoan(amount, interest, loanToCollateral, duration);
        vm.stopPrank();

        // Clear the request (lender is this contract dummy)
        uint256 neededCollateral = c.collateralFor(amount, loanToCollateral);
        deal(address(c.collateral()), address(c), 1e24);
        deal(address(c.debt()), address(c), 1e24);
        c.collateral().approve(address(c), type(uint256).max);
        c.debt().approve(address(c), type(uint256).max);
        vm.prank(address(0xa11ce));  // dummy lender
        c.clearRequest(reqId, false, false);

        // Get the loan ID (the only one)
        uint256 loanId = 0;

        // Approve transfer from dummy lender to newOwner
        vm.prank(address(0xa11ce));
        c.approveTransfer(newOwner, loanId);

        // Transfer ownership to newOwner
        vm.prank(newOwner);
        c.transferOwnership(loanId);

        // Warp past expiry
        vm.warp(block.timestamp + duration + 1);

        // New owner claims defaulted; in reference, collateral transfers to newOwner
        // In bug, collateral is not returned to owner but we check newOwner balance before and after
        uint256 balanceBefore = c.collateral().balanceOf(newOwner);
        vm.prank(newOwner);
        (uint256 returnedDebt, uint256 returnedCollateral,) = c.claimDefaulted(loanId);
        uint256 balanceAfter = c.collateral().balanceOf(newOwner);

