        amount = bound(amount, 1e6, 1e24);
        interest = bound(interest, 1, 1e18);
        loanToCollateral = bound(loanToCollateral, 1, 1e18);
        duration = bound(duration, 1 days, 365 days);

        // Create loan via request + clear
        uint256 collateralAmount = c.collateralFor(amount, loanToCollateral);
        vm.assume(collateralAmount > 0);

        // Give borrower enough collateral tokens
        address collateralToken = address(c.collateral());
        address debtToken = address(c.debt());
        deal(collateralToken, borrower, collateralAmount);
        deal(debtToken, originalLender, amount);

        // Borrower requests loan
        vm.startPrank(borrower);
        ERC20(collateralToken).approve(address(c), collateralAmount);
        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration);
        vm.stopPrank();

        // Clear request
        vm.startPrank(originalLender);
        ERC20(debtToken).approve(address(c), amount);
        uint256 loanID = c.clearRequest(reqID, false, false);
        vm.stopPrank();

        // Transfer ownership to newLender
        vm.prank(originalLender);
        c.approveTransfer(newLender, loanID);
        vm.prank(newLender);
        c.transferOwnership(loanID);

        // Get loan details to compute repayment
        ( , uint256 loanAmount, , , , , , ) = c.getLoan(loanID);
        uint256 repayAmount = bound(uint256(keccak256(abi.encode(loanID, 1))), 1, loanAmount);

        // get debt balance of newLender before repay
        uint256 balanceBefore = ERC20(debtToken).balanceOf(newLender);

        // Repay loan
        vm.startPrank(borrower);
        deal(debtToken, borrower, repayAmount);
        ERC20(debtToken).approve(address(c), repayAmount);
        c.repayLoan(loanID, repayAmount);
        vm.stopPrank();

        // get debt balance of newLender after repay
        uint256 balanceAfter = ERC20(debtToken).balanceOf(newLender);

        // Rule: The new lender should NOT have received any debt (since repayDirect is false, debt goes to contract)
        // So his balance should remain the same
        assertTrue(balanceAfter == balanceBefore, "New lender's debt balance should not change on repay");
    }
}

